const INDEX_HTML = "<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Transparência Brasil | Monitor de Gastos Públicos, PNCP, SICONFI e Radar Anti-Corrupção</title>\n  <meta name=\"description\" content=\"Consulte gastos públicos do Governo Federal, Estados e Municípios em tempo real. Auditoria cidadã oficial integrada ao Portal da Transparência (CGU), SICONFI (Tesouro Nacional), PNCP e Radar Anti-Corrupção (TCU).\">\n  <meta name=\"keywords\" content=\"gastos públicos, transparência brasil, portal da transparência, gastos do governo, auditoria cidadã, radar anticorrupção, licitações pncp, siconfi tesouro nacional, tcu inidôneos, orçamento público\">\n  <meta name=\"robots\" content=\"index, follow, max-image-preview:large, max-snippet:-1\">\n  <link rel=\"canonical\" href=\"https://transparencia.admx.tech/\">\n  <meta property=\"og:type\" content=\"website\">\n  <meta property=\"og:locale\" content=\"pt_BR\">\n  <meta property=\"og:site_name\" content=\"Transparência Brasil — Monitor de Gastos Públicos\">\n  <meta property=\"og:title\" content=\"Transparência Brasil | Gastos Públicos e Radar Anti-Corrupção\">\n  <meta property=\"og:description\" content=\"Plataforma de inteligência fiscal e auditoria cidadã com dados oficiais reais do PNCP, SICONFI/Tesouro Nacional, CGU e TCU.\">\n  <meta property=\"og:url\" content=\"https://transparencia.admx.tech/\">\n  <meta name=\"twitter:card\" content=\"summary_large_image\">\n  <meta name=\"twitter:title\" content=\"Transparência Brasil | Monitor de Gastos Públicos\">\n  <meta name=\"twitter:description\" content=\"Rastreabilidade ponta a ponta de despesas públicas, contratos PNCP, SICONFI e Radar Anti-Corrupção com hash SHA-256.\">\n  <script type=\"application/ld+json\">\n  {\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"DataCatalog\",\n    \"name\": \"Transparência Brasil — Monitor de Gastos Públicos e Radar Anti-Corrupção\",\n    \"url\": \"https://transparencia.admx.tech/\",\n    \"alternateName\": [\"Fiscaliza Brasil\", \"Gastos Públicos Brasil\"],\n    \"description\": \"Plataforma de transparência pública e controle social baseada na Lei nº 4.320/1964, LRF e LAI, integrando dados oficiais reais do PNCP, SICONFI/Tesouro Nacional, CGU e TCU.\",\n    \"inLanguage\": \"pt-BR\",\n    \"license\": \"https://creativecommons.org/licenses/by/4.0/\"\n  }\n  </script>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Public+Sans:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n  <link rel=\"stylesheet\" href=\"/static/css/app.css\">\n  <script src=\"https://cdn.tailwindcss.com\"></script>\n</head>\n<body class=\"min-h-screen font-sans antialiased bg-[#f8fafc] text-slate-900\">\n\n  <!-- CABEÇALHO INSTITUCIONAL EM LARGURA TOTAL -->\n  <header class=\"border-b border-slate-200 bg-white sticky top-0 z-40\">\n    <div class=\"w-full px-4 sm:px-6 lg:px-8 xl:px-10 h-16 flex items-center justify-between gap-4\">\n      <div class=\"flex items-center gap-3.5\">\n        <!-- Brasão / Insígnia Vetorial Brasil -->\n        <div class=\"h-10 w-10 rounded-xl bg-[#00853b] flex items-center justify-center border border-slate-200 shrink-0\">\n          <svg class=\"w-7 h-5\" viewBox=\"0 0 72 50\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\" aria-label=\"Bandeira do Brasil\">\n            <rect width=\"72\" height=\"50\" rx=\"4\" fill=\"#00853B\"/>\n            <polygon points=\"36,4 67,25 36,46 5,25\" fill=\"#FFDF00\"/>\n            <circle cx=\"36\" cy=\"25\" r=\"13\" fill=\"#002776\"/>\n            <path d=\"M23.5 25.5C27 22.5 35 22 48.5 26.5\" stroke=\"#FFFFFF\" stroke-width=\"2.5\" stroke-linecap=\"round\"/>\n          </svg>\n        </div>\n        <div>\n          <div class=\"flex items-center gap-2\">\n            <h1 class=\"text-base sm:text-lg font-extrabold text-slate-900 tracking-tight flex items-center gap-1.5\">\n              <span>Transparência</span>\n              <span class=\"text-[#002776]\">Brasil</span>\n            </h1>\n            <span class=\"px-2 py-0.5 text-[11px] font-bold bg-emerald-50 text-emerald-700 border border-emerald-200 rounded-full\">\n              Oficial & Auditado\n            </span>\n          </div>\n          <p class=\"text-xs text-slate-600 hidden md:block\">\n            Portal da Transparência (CGU) • SICONFI (Tesouro Nacional) • PNCP • Lei nº 4.320/64\n          </p>\n        </div>\n      </div>\n\n      <!-- CONTROLES SUPERIORES & ALERTA VERMELHO DE CORRUPÇÃO -->\n      <div class=\"flex items-center gap-2 sm:gap-3\">\n        <!-- Pílula Vermelha de Alerta de Corrupção -->\n        <button id=\"btnIrParaRadar\" class=\"flex items-center gap-2 px-3 py-1.5 bg-red-50 hover:bg-red-100 border border-red-300 rounded-lg text-xs font-bold text-red-800 transition-all group\">\n          <svg class=\"w-4 h-4 text-red-600 shrink-0 animate-pulse\" viewBox=\"0 0 20 20\" fill=\"currentColor\">\n            <path fill-rule=\"evenodd\" d=\"M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z\" clip-rule=\"evenodd\"/>\n          </svg>\n          <span class=\"hidden sm:inline\">Radar de Corrupção:</span>\n          <span class=\"bg-[#dc2626] text-white px-2 py-0.5 rounded font-mono text-[11px] tabular-nums font-bold\" id=\"headerQtdCorrupcao\">3 Indícios</span>\n        </button>\n\n        <!-- SELETOR DE MODO -->\n        <div class=\"inline-flex rounded-lg border border-slate-200 overflow-hidden text-xs font-medium\">\n          <button id=\"btnModoCidadao\" class=\"px-3 py-1.5 bg-slate-900 text-white font-bold transition-colors\">\n            Visão Cidadã\n          </button>\n          <button id=\"btnModoAuditor\" class=\"px-3 py-1.5 bg-white text-slate-600 hover:text-slate-900 transition-colors\">\n            Modo Auditor\n          </button>\n        </div>\n\n        <button id=\"btnExecutarPipeline\" class=\"hidden lg:inline-flex items-center gap-1.5 px-3 py-1.5 bg-white hover:bg-slate-50 border border-slate-200 text-xs font-semibold text-slate-700 rounded-lg transition-colors\">\n          <span class=\"inline-block w-2 h-2 rounded-full bg-[#00853b]\"></span>\n          Sincronizar\n        </button>\n      </div>\n    </div>\n  </header>\n\n  <!-- CONTEÚDO PRINCIPAL EM LARGURA TOTAL E LAYOUT LIMPO -->\n  <main class=\"w-full px-4 sm:px-6 lg:px-8 xl:px-10 py-5 space-y-5\">\n\n    <!-- FAIXA EXECUTIVA LIMPA (SEM HERO BULKY) -->\n    <section class=\"flex flex-col md:flex-row md:items-center justify-between gap-3 pb-2 border-b border-slate-200\">\n      <div class=\"space-y-0.5\">\n        <h2 class=\"text-lg sm:text-xl font-extrabold text-slate-900 tracking-tight\">\n          Painel de Execução Orçamentária e Fiscalização Cívica\n        </h2>\n        <p class=\"text-xs text-slate-600\">\n          Dados consolidados de despesas da União, Estados e Municípios com rastreabilidade SHA-256 e isolamento contra dupla contagem. <strong class=\"text-red-700 font-bold\">Indícios de irregularidade e empresas do CEIS/CGU sinalizados exclusivamente em Vermelho.</strong>\n        </p>\n      </div>\n      <div class=\"flex items-center gap-4 shrink-0\">\n        <div class=\"flex items-center gap-2 text-xs text-slate-600\">\n          <span class=\"inline-block w-2 h-2 rounded-full bg-emerald-500\"></span>\n          <span>Base Analítica Conciliada</span>\n        </div>\n        <div class=\"text-right pl-4 border-l border-slate-200\">\n          <span class=\"text-[10px] uppercase font-bold text-slate-400 block tracking-wider\">Exercício</span>\n          <span class=\"text-base font-extrabold text-[#002776] font-mono tabular-nums leading-none\">2026</span>\n        </div>\n      </div>\n    </section>\n\n    <!-- SCORECARDS / KPIS EM LARGURA TOTAL (5 COLUNAS FLUIDAS) -->\n    <section class=\"grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-3.5\" id=\"kpiContainer\">\n      \n      <!-- Card 1: Gasto Efetivo Real (Verde Institucional) -->\n      <div class=\"card-analitico relative overflow-hidden group\">\n        <div class=\"text-xs font-bold text-emerald-800 uppercase tracking-wider flex items-center justify-between\">\n          <span>Gasto Efetivo Líquido</span>\n          <svg class=\"w-3.5 h-3.5 text-emerald-600\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\">\n            <path fill-rule=\"evenodd\" d=\"M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z\" clip-rule=\"evenodd\"/>\n          </svg>\n        </div>\n        <div class=\"mt-2 text-xl sm:text-2xl font-black text-slate-900 font-mono tabular-nums tracking-tight\" id=\"kpiGastoEfetivo\">\n          Carregando...\n        </div>\n        <div class=\"mt-1 text-[11px] text-emerald-700 font-medium\">\n          Pagamento líquido sem repasses duplicados\n        </div>\n      </div>\n\n      <!-- Card 2: Total Pago no Exercício (Azul) -->\n      <div class=\"card-analitico\">\n        <div class=\"text-xs font-bold text-slate-700 uppercase tracking-wider\">\n          Total Pago (Exercício)\n        </div>\n        <div class=\"mt-2 text-xl sm:text-2xl font-black text-slate-900 font-mono tabular-nums tracking-tight\" id=\"kpiTotalPago\">\n          ...\n        </div>\n        <div class=\"mt-1 text-[11px] text-slate-600\">\n          Ordens Bancárias (OBs) liquidadas\n        </div>\n      </div>\n\n      <!-- Card 3: Restos a Pagar Pagos (Âmbar) -->\n      <div class=\"card-analitico\">\n        <div class=\"text-xs font-bold text-amber-800 uppercase tracking-wider\">\n          Restos a Pagar (RAP)\n        </div>\n        <div class=\"mt-2 text-xl sm:text-2xl font-black text-amber-900 font-mono tabular-nums tracking-tight\" id=\"kpiRapPagos\">\n          ...\n        </div>\n        <div class=\"mt-1 text-[11px] text-amber-700\">\n          Compromissos de anos anteriores\n        </div>\n      </div>\n\n      <!-- Card 4: Transferências Fundo a Fundo (Celeste) -->\n      <div class=\"card-analitico\">\n        <div class=\"text-xs font-bold text-sky-800 uppercase tracking-wider\">\n          Repasses / Fundo a Fundo\n        </div>\n        <div class=\"mt-2 text-xl sm:text-2xl font-black text-slate-900 font-mono tabular-nums tracking-tight\" id=\"kpiTransferencias\">\n          ...\n        </div>\n        <div class=\"mt-1 text-[11px] text-sky-700\">\n          Transferências a Estados e Municípios\n        </div>\n      </div>\n\n      <!-- Card 5: VERMELHO EXCLUSIVO PARA CORRUPÇÃO -->\n      <div class=\"card-corrupcao-alerta relative overflow-hidden group cursor-pointer\" onclick=\"navegarParaAba('tabRadarCorrupcao')\">\n        <div class=\"text-xs font-extrabold text-red-800 uppercase tracking-wider flex items-center justify-between\">\n          <span class=\"flex items-center gap-1.5\">\n            <svg class=\"w-3.5 h-3.5 text-red-600 animate-pulse\" viewBox=\"0 0 20 20\" fill=\"currentColor\">\n              <path fill-rule=\"evenodd\" d=\"M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z\" clip-rule=\"evenodd\"/>\n            </svg>\n            Alerta de Corrupção\n          </span>\n          <span class=\"text-red-700 text-xs font-mono tabular-nums font-bold\" id=\"kpiTotalAlertasCorrupcao\">3 Casos</span>\n        </div>\n        <div class=\"mt-2 text-xl sm:text-2xl font-black text-red-700 font-mono tabular-nums tracking-tight\" id=\"kpiValorCorrupcao\">\n          R$ 59.150.000,00\n        </div>\n        <div class=\"mt-1 text-[11px] text-red-800 font-medium flex items-center justify-between\">\n          <span>Sob auditoria do TCU / CGU</span>\n          <span class=\"text-red-700 group-hover:translate-x-1 transition-transform font-bold\">Ver &rarr;</span>\n        </div>\n      </div>\n\n    </section>\n\n    <!-- FUNIL ORÇAMENTÁRIO (LEI 4.320/64) - NO MODO AUDITOR -->\n    <section id=\"funilOrcamentarioSection\" class=\"hidden space-y-3\">\n      <div class=\"flex items-center justify-between border-b border-slate-200 pb-2\">\n        <div>\n          <h3 class=\"text-sm sm:text-base font-bold text-slate-900 flex items-center gap-2\">\n            <svg class=\"w-4 h-4 text-[#002776]\" viewBox=\"0 0 20 20\" fill=\"currentColor\">\n              <path fill-rule=\"evenodd\" d=\"M3 3a1 1 0 011-1h12a1 1 0 011 1v3a1 1 0 01-.293.707L12 11.414V15a1 1 0 01-.293.707l-2 2A1 1 0 018 17v-5.586L3.293 6.707A1 1 0 013 6V3z\" clip-rule=\"evenodd\"/>\n            </svg>\n            <span>Funil do Ciclo da Despesa Pública (Lei 4.320/1964)</span>\n          </h3>\n          <p class=\"text-xs text-slate-600\">Métricas sequenciais: Empenho Líquido &rarr; Liquidação Atestada &rarr; Pagamento Direto &rarr; Repasses</p>\n        </div>\n        <span class=\"text-xs px-2.5 py-0.5 bg-blue-50 text-[#002776] border border-blue-200 rounded-full font-mono font-semibold\">\n          Filtro Contábil\n        </span>\n      </div>\n\n      <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3.5\">\n        <div class=\"card-analitico\">\n          <div class=\"text-[11px] text-amber-800 font-bold uppercase\">1. Empenho Líquido (NE)</div>\n          <div class=\"text-lg font-bold font-mono tabular-nums text-slate-900 mt-1\" id=\"funilEmpenho\">...</div>\n          <p class=\"text-[11px] text-slate-600 mt-1\">Dotação reservada por Nota de Empenho.</p>\n        </div>\n\n        <div class=\"card-analitico\">\n          <div class=\"text-[11px] text-blue-700 font-bold uppercase\">2. Liquidação Atestada (NL)</div>\n          <div class=\"text-lg font-bold font-mono tabular-nums text-slate-900 mt-1\" id=\"funilLiquidado\">...</div>\n          <p class=\"text-[11px] text-slate-600 mt-1\">Entrega atestada e obrigação reconhecida.</p>\n        </div>\n\n        <div class=\"card-analitico\">\n          <div class=\"text-[11px] text-emerald-700 font-bold uppercase\">3. Pagamento Direto (OB)</div>\n          <div class=\"text-lg font-bold font-mono tabular-nums text-slate-900 mt-1\" id=\"funilPago\">...</div>\n          <p class=\"text-[11px] text-slate-600 mt-1\">Saída de caixa para fornecedor do serviço.</p>\n        </div>\n\n        <div class=\"card-analitico\">\n          <div class=\"text-[11px] text-sky-700 font-bold uppercase\">4. Repasses (FNS/FPM)</div>\n          <div class=\"text-lg font-bold font-mono tabular-nums text-slate-900 mt-1\" id=\"funilRepasses\">...</div>\n          <p class=\"text-[11px] text-slate-600 mt-1\">Transferidos aos fundos municipais/estaduais.</p>\n        </div>\n      </div>\n    </section>\n\n    <!-- NAVEGAÇÃO EM ABAS (LARGURA TOTAL) -->\n    <div class=\"border-b border-slate-200 flex gap-1 overflow-x-auto pb-0.5\" id=\"tabNav\">\n      <!-- ABA VERMELHA DE ALERTA DE CORRUPÇÃO EM DESTAQUE MÁXIMO -->\n      <button data-tab=\"tabRadarCorrupcao\" class=\"tab-btn active tab-btn-corrupcao rounded-t-lg border-b-2 border-red-600 text-red-700 bg-red-50 flex items-center gap-2 font-bold\">\n        <svg class=\"w-4 h-4 text-red-600 shrink-0\" viewBox=\"0 0 20 20\" fill=\"currentColor\">\n          <path fill-rule=\"evenodd\" d=\"M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z\" clip-rule=\"evenodd\"/>\n        </svg>\n        <span>Radar Anti-Corrupção (Maiores Valores)</span>\n        <span id=\"tabQtdCorrupcao\" class=\"bg-[#dc2626] text-white text-[10px] px-1.5 py-0.2 rounded-full font-mono tabular-nums font-bold\">...</span>\n      </button>\n\n      <!-- ABA ECONOMIA: PLANO DE GOVERNO VS. REALIDADE EXECUTADA -->\n      <button data-tab=\"tabEconomia\" class=\"tab-btn rounded-t-lg border-b-2 border-transparent text-slate-600 hover:text-slate-900 flex items-center gap-2 font-bold\">\n        <svg class=\"w-4 h-4 text-[#002776] shrink-0\" viewBox=\"0 0 20 20\" fill=\"currentColor\">\n          <path d=\"M2 11a1 1 0 011-1h2a1 1 0 011 1v5a1 1 0 01-1 1H3a1 1 0 01-1-1v-5zM8 7a1 1 0 011-1h2a1 1 0 011 1v9a1 1 0 01-1 1H9a1 1 0 01-1-1V7zM14 4a1 1 0 011-1h2a1 1 0 011 1v12a1 1 0 01-1 1h-2a1 1 0 01-1-1V4z\"/>\n        </svg>\n        <span>Economia: Plano vs. Realidade</span>\n      </button>\n\n      <button data-tab=\"tabGeral\" class=\"tab-btn rounded-t-lg border-b-2 border-transparent text-slate-600 hover:text-slate-900 flex items-center gap-2\">\n        <svg class=\"w-4 h-4 text-slate-600\" viewBox=\"0 0 20 20\" fill=\"currentColor\">\n          <path fill-rule=\"evenodd\" d=\"M4 4a2 2 0 012-2h8a2 2 0 012 2v12a1 1 0 110 2h-3a1 1 0 01-1-1v-2a1 1 0 00-1-1H9a1 1 0 00-1 1v2a1 1 0 01-1 1H4a1 1 0 110-2V4zm3 1h2v2H7V5zm2 4H7v2h2V9zm2-4h2v2h-2V5zm2 4h-2v2h2V9z\" clip-rule=\"evenodd\"/>\n        </svg>\n        <span>Ministérios & Funções</span>\n      </button>\n\n      <button data-tab=\"tabMunicipios\" class=\"tab-btn rounded-t-lg border-b-2 border-transparent text-slate-600 hover:text-slate-900 flex items-center gap-2\">\n        <svg class=\"w-4 h-4 text-slate-400\" viewBox=\"0 0 20 20\" fill=\"currentColor\">\n          <path fill-rule=\"evenodd\" d=\"M5.05 4.05a7 7 0 119.9 9.9L10 18.9l-4.95-4.95a7 7 0 010-9.9zM10 11a2 2 0 100-4 2 2 0 000 4z\" clip-rule=\"evenodd\"/>\n        </svg>\n        <span>Estados & Municípios (SICONFI)</span>\n      </button>\n\n      <button data-tab=\"tabContratos\" class=\"tab-btn rounded-t-lg border-b-2 border-transparent text-slate-600 hover:text-slate-900 flex items-center gap-2\">\n        <svg class=\"w-4 h-4 text-slate-400\" viewBox=\"0 0 20 20\" fill=\"currentColor\">\n          <path fill-rule=\"evenodd\" d=\"M4 4a2 2 0 012-2h4.586A2 2 0 0112 2.586L15.414 6A2 2 0 0116 7.414V16a2 2 0 01-2 2H6a2 2 0 01-2-2V4zm2 6a1 1 0 011-1h6a1 1 0 110 2H7a1 1 0 01-1-1zm1 3a1 1 0 100 2h6a1 1 0 100-2H7z\" clip-rule=\"evenodd\"/>\n        </svg>\n        <span>Contratações Públicas (PNCP)</span>\n      </button>\n\n      <button data-tab=\"tabFornecedores\" class=\"tab-btn rounded-t-lg border-b-2 border-transparent text-slate-600 hover:text-slate-900 flex items-center gap-2\">\n        <svg class=\"w-4 h-4 text-slate-400\" viewBox=\"0 0 20 20\" fill=\"currentColor\">\n          <path fill-rule=\"evenodd\" d=\"M6 6V5a3 3 0 013-3h2a3 3 0 013 3v1h2a2 2 0 012 2v3.57A22.952 22.952 0 0110 13a22.95 22.95 0 01-8-1.43V8a2 2 0 012-2h2zm2-1a1 1 0 011-1h2a1 1 0 011 1v1H8V5zm1 5a1 1 0 011-1h.01a1 1 0 110 2H10a1 1 0 01-1-1z\" clip-rule=\"evenodd\"/>\n        </svg>\n        <span>Top Fornecedores & Credores</span>\n      </button>\n\n      <button data-tab=\"tabGranular\" class=\"tab-btn rounded-t-lg border-b-2 border-transparent text-slate-600 hover:text-slate-900 flex items-center gap-2\">\n        <svg class=\"w-4 h-4 text-slate-400\" viewBox=\"0 0 20 20\" fill=\"currentColor\">\n          <path fill-rule=\"evenodd\" d=\"M8 4a4 4 0 100 8 4 4 0 000-8zM2 8a6 6 0 1110.89 3.476l4.817 4.817a1 1 0 01-1.414 1.414l-4.816-4.816A6 6 0 012 8z\" clip-rule=\"evenodd\"/>\n        </svg>\n        <span>Consulta Granular & Rastrear</span>\n      </button>\n    </div>\n\n    <!-- TAB 0: RADAR ANTI-CORRUPÇÃO (DESTAQUE VERMELHO) -->\n    <section id=\"tabRadarCorrupcao\" class=\"tab-content space-y-4\">\n      <div class=\"border-b border-red-200 pb-3 flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n        <div class=\"space-y-0.5\">\n          <div class=\"flex items-center gap-2\">\n            <svg class=\"w-5 h-5 text-red-600 shrink-0\" viewBox=\"0 0 20 20\" fill=\"currentColor\">\n              <path fill-rule=\"evenodd\" d=\"M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z\" clip-rule=\"evenodd\"/>\n            </svg>\n            <h3 class=\"text-base font-black text-red-900 tracking-tight uppercase\">\n              Radar de Indícios de Irregularidade e Suspeita de Corrupção\n            </h3>\n          </div>\n          <p class=\"text-xs text-slate-600\">\n            Casos sinalizados pelo motor analítico: empresas punidas no CEIS/CGU, sobrepreço atípico e fracionamento ilegal.\n          </p>\n        </div>\n        <div class=\"flex items-center gap-2 shrink-0\">\n          <a href=\"/api/v1/exportar/despesas.csv?ano=2026&apenas_corrupcao=true\" download class=\"px-3.5 py-1.5 bg-[#dc2626] hover:bg-[#b91c1c] text-white rounded-lg text-xs font-bold transition-all flex items-center gap-1.5 shadow-xs\">\n            <svg class=\"w-4 h-4\" viewBox=\"0 0 20 20\" fill=\"currentColor\">\n              <path fill-rule=\"evenodd\" d=\"M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L9 10.586V3a1 1 0 112 0v7.586l1.293-1.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z\" clip-rule=\"evenodd\"/>\n            </svg>\n            <span>Baixar Dossiê (CSV)</span>\n          </a>\n          <span class=\"px-3 py-1.5 bg-red-50 text-red-800 border border-red-200 rounded-lg text-xs font-bold font-mono\">\n            Controle Social\n          </span>\n        </div>\n      </div>\n\n      <!-- Grid de Casos de Corrupção em Largura Total -->\n      <div class=\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4\" id=\"gridCasosCorrupcao\">\n        <div class=\"col-span-3 py-8 text-center text-xs text-red-600\">Carregando alertas do Radar Anti-Corrupção...</div>\n      </div>\n    </section>\n\n    <!-- TAB ECONOMIA: PLANO DE GOVERNO VS. REALIDADE EXECUTADA (BCB + SICONFI UNIÃO) -->\n    <section id=\"tabEconomia\" class=\"tab-content hidden space-y-5\">\n      <div class=\"border-b border-slate-200 pb-3 flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n        <div class=\"space-y-0.5\">\n          <h3 class=\"text-base font-black text-slate-900 tracking-tight uppercase\">\n            Auditoria Econômica: Plano Prometido (LDO/LOA) vs. Eficazmente Colocado em Prática\n          </h3>\n          <p class=\"text-xs text-slate-600\">\n            Confronto direto entre as metas oficiais do governo e os dados reais do Banco Central do Brasil (SGS) e do Balanço da União no Tesouro Nacional (SICONFI), ordenado pelos valores mais elevados.\n          </p>\n        </div>\n        <span class=\"px-3 py-1.5 bg-red-50 text-red-800 border border-red-200 rounded-lg text-xs font-bold font-mono shrink-0\">\n          Fonte: BCB (SGS) + SICONFI União (id_ente=1)\n        </span>\n      </div>\n\n      <!-- Grid de Indicadores Macroeconômicos (Plano vs. Realidade) -->\n      <div class=\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4\" id=\"gridIndicadoresEconomia\">\n        <div class=\"col-span-4 py-6 text-center text-xs text-slate-600\">Carregando indicadores oficiais do Banco Central e Tesouro Nacional...</div>\n      </div>\n\n      <!-- Tabela Comparativa de Execução Orçamentária da União (Do Maior para o Menor Valor) -->\n      <div class=\"card-analitico space-y-4\">\n        <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-200 pb-3\">\n          <div>\n            <h3 class=\"text-sm font-bold text-slate-900 uppercase tracking-wider\">\n              Orçamento Prometido vs. Efetivamente Entregue por Área (União Federal)\n            </h3>\n            <p class=\"text-xs text-slate-600\">\n              Ordenado rigorosamente pelos valores mais elevados (RREO Anexo 02 da União — Tesouro Nacional). Em vermelho: áreas com paralisia de execução ou retenção bilionária em Restos a Pagar.\n            </p>\n          </div>\n          <span class=\"text-[11px] font-mono text-red-800 bg-red-50 px-2.5 py-1 rounded-md border border-red-200 font-semibold shrink-0\">\n            Ordem: Maiores Valores Primeiro\n          </span>\n        </div>\n\n        <div class=\"overflow-x-auto\">\n          <table class=\"tabela-limpa\">\n            <thead>\n              <tr>\n                <th>Função / Promessa no Plano de Governo</th>\n                <th class=\"text-right\">Planejado (LOA)</th>\n                <th class=\"text-right\">Efetivamente Executado</th>\n                <th class=\"text-right\">% Entregue</th>\n                <th class=\"text-right\">Travado em RAP (Não Entregue)</th>\n                <th>Diagnóstico Forense de Execução</th>\n              </tr>\n            </thead>\n            <tbody id=\"tabelaEconomiaSetorial\" class=\"divide-y divide-slate-100\">\n              <tr><td colspan=\"6\" class=\"py-4 text-center text-slate-600\">Carregando balanço de execução da União...</td></tr>\n            </tbody>\n          </table>\n        </div>\n      </div>\n    </section>\n\n    <!-- TAB 1: GERAL & MINISTÉRIOS (EM 2 COLUNAS LARGAS) -->\n    <section id=\"tabGeral\" class=\"tab-content hidden space-y-4\">\n      <div class=\"grid grid-cols-1 lg:grid-cols-2 gap-5\">\n        <!-- Ranking de Órgãos Superiores -->\n        <div class=\"card-analitico space-y-4\">\n          <div class=\"flex items-center justify-between border-b border-slate-200 pb-3\">\n            <div>\n              <h3 class=\"text-sm font-bold text-slate-900 uppercase tracking-wider\">Top Ministérios & Órgãos</h3>\n              <p class=\"text-xs text-slate-600\">Classificação por despesas pagas no ano</p>\n            </div>\n            <span class=\"text-[11px] font-mono text-emerald-700 font-semibold\">Fonte: CGU / SIAFI</span>\n          </div>\n          <div class=\"divide-y divide-slate-100\" id=\"listaOrgaos\">\n            <div class=\"py-4 text-center text-xs text-slate-400\">Carregando ministérios...</div>\n          </div>\n        </div>\n\n        <!-- Distribuição por Função de Governo -->\n        <div class=\"card-analitico space-y-4\">\n          <div class=\"flex items-center justify-between border-b border-slate-200 pb-3\">\n            <div>\n              <h3 class=\"text-sm font-bold text-slate-900 uppercase tracking-wider\">Distribuição por Área</h3>\n              <p class=\"text-xs text-slate-600\">Saúde, Educação, Infraestrutura e Segurança</p>\n            </div>\n            <span class=\"text-[11px] font-mono text-[#002776] font-semibold\">Classificação Funcional</span>\n          </div>\n          <div class=\"space-y-3.5 pt-2\" id=\"listaFuncoes\">\n            <div class=\"py-4 text-center text-xs text-slate-400\">Carregando funções de governo...</div>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <!-- TAB 2: ESTADOS E MUNICÍPIOS (SICONFI EM LARGURA TOTAL) -->\n    <section id=\"tabMunicipios\" class=\"tab-content hidden space-y-4\">\n      <div class=\"card-analitico space-y-4\">\n        <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-200 pb-3\">\n          <div>\n            <h3 class=\"text-sm font-bold text-slate-900 uppercase tracking-wider\">Comparador Fiscal e Gasto per Capita</h3>\n            <p class=\"text-xs text-slate-600\">Demonstrativos fiscais enviados ao Tesouro Nacional (RREO/RGF) cruzados com a população do IBGE</p>\n          </div>\n          <span class=\"text-[11px] font-mono text-emerald-800 bg-emerald-50 px-2.5 py-1 rounded-md border border-emerald-200 font-semibold\">\n            Cobertura SICONFI: 100% Capitais\n          </span>\n        </div>\n\n        <div class=\"overflow-x-auto\">\n          <table class=\"tabela-limpa\">\n            <thead>\n              <tr>\n                <th>Município / UF</th>\n                <th class=\"text-right\">População (IBGE)</th>\n                <th class=\"text-right\">Gasto per Capita</th>\n                <th class=\"text-right\">Gasto em Saúde</th>\n                <th class=\"text-right\">Gasto em Educação</th>\n                <th class=\"text-right\">Total Pago</th>\n                <th class=\"text-right\">Comprovante</th>\n              </tr>\n            </thead>\n            <tbody id=\"tabelaMunicipios\" class=\"divide-y divide-slate-100\">\n              <tr><td colspan=\"7\" class=\"py-4 text-center text-slate-400\">Carregando dados municipais...</td></tr>\n            </tbody>\n          </table>\n        </div>\n      </div>\n    </section>\n\n    <!-- TAB 3: CONTRATAÇÕES PÚBLICAS (PNCP EM LARGURA TOTAL) -->\n    <section id=\"tabContratos\" class=\"tab-content hidden space-y-4\">\n      <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-200 pb-3\">\n        <div>\n          <h3 class=\"text-sm font-bold text-slate-900 uppercase tracking-wider\">Contratos Registrados no PNCP</h3>\n          <p class=\"text-xs text-slate-600\">Editais homologados e valores contratados sob a Nova Lei de Licitações (Lei nº 14.133/2021)</p>\n        </div>\n        <span class=\"text-[11px] font-mono text-[#002776] bg-blue-50 px-2.5 py-1 rounded-md border border-blue-200 font-semibold\">\n          API PNCP Oficial\n        </span>\n      </div>\n\n      <div class=\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4\" id=\"cardsContratos\">\n        <div class=\"col-span-3 py-4 text-center text-xs text-slate-400\">Carregando contratos do PNCP...</div>\n      </div>\n    </section>\n\n    <!-- TAB 4: FORNECEDORES & CREDORES (LARGURA TOTAL) -->\n    <section id=\"tabFornecedores\" class=\"tab-content hidden space-y-4\">\n      <div class=\"card-analitico space-y-4\">\n        <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-200 pb-3\">\n          <div>\n            <h3 class=\"text-sm font-bold text-slate-900 uppercase tracking-wider\">Top Recebedores de Recursos Públicos</h3>\n            <p class=\"text-xs text-slate-600\">Maiores credores em volume financeiro pago pelo Tesouro Nacional</p>\n          </div>\n          <span class=\"text-[11px] font-mono text-amber-800 bg-amber-50 px-2.5 py-1 rounded-md border border-amber-200 font-semibold\">\n            Controle Social & Compliance\n          </span>\n        </div>\n\n        <div class=\"overflow-x-auto\">\n          <table class=\"tabela-limpa\">\n            <thead>\n              <tr>\n                <th>Razão Social / Nome</th>\n                <th>CNPJ / CPF</th>\n                <th>Tipo</th>\n                <th class=\"text-right\">Ordens Bancárias</th>\n                <th class=\"text-right\">Total Recebido</th>\n                <th class=\"text-right\">Rastrear</th>\n              </tr>\n            </thead>\n            <tbody id=\"tabelaFornecedores\" class=\"divide-y divide-slate-100\">\n              <tr><td colspan=\"6\" class=\"py-4 text-center text-slate-400\">Carregando fornecedores...</td></tr>\n            </tbody>\n          </table>\n        </div>\n      </div>\n    </section>\n\n    <!-- TAB 5: BUSCA GRANULAR (LARGURA TOTAL E BARRA DE BUSCA EXPANDIDA) -->\n    <section id=\"tabGranular\" class=\"tab-content hidden space-y-4\">\n      <div class=\"card-analitico space-y-4\">\n        <div class=\"flex flex-col lg:flex-row lg:items-center justify-between gap-3 border-b border-slate-200 pb-3\">\n          <div>\n            <h3 class=\"text-sm font-bold text-slate-900 uppercase tracking-wider\">Consulta Granular de Despesas</h3>\n            <p class=\"text-xs text-slate-600\">Linhas sob suspeita do Radar Anti-Corrupção exibem badge exclusivo em Vermelho</p>\n          </div>\n          <div class=\"flex flex-wrap items-center gap-2.5\">\n            <label class=\"flex items-center gap-1.5 px-3 py-1.5 bg-red-50 border border-red-300 rounded-lg text-xs text-red-800 font-bold cursor-pointer hover:bg-red-100 transition-colors shrink-0\">\n              <input type=\"checkbox\" id=\"checkApenasCorrupcao\" class=\"accent-red-600 rounded\">\n              <span>Apenas Alertas de Corrupção</span>\n            </label>\n            <input type=\"text\" id=\"campoBusca\" placeholder=\"Pesquisar favorecido, documento...\" class=\"bg-white border border-slate-300 rounded-lg px-3 py-1.5 text-xs text-slate-900 placeholder-slate-400 focus:outline-none focus:border-[#002776] w-64 md:w-80\">\n            <button id=\"btnBuscar\" class=\"px-4 py-1.5 bg-[#00853b] hover:bg-[#006b2f] text-white rounded-lg text-xs font-bold transition-colors shrink-0\">\n              Buscar\n            </button>\n            <a href=\"/api/v1/exportar/despesas.csv?ano=2026\" download id=\"linkExportarCsv\" class=\"px-3.5 py-1.5 bg-white hover:bg-slate-50 text-slate-700 border border-slate-200 rounded-lg text-xs font-bold transition-all flex items-center gap-1.5 shadow-xs shrink-0\">\n              <svg class=\"w-3.5 h-3.5\" viewBox=\"0 0 20 20\" fill=\"currentColor\">\n                <path fill-rule=\"evenodd\" d=\"M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L9 10.586V3a1 1 0 112 0v7.586l1.293-1.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z\" clip-rule=\"evenodd\"/>\n              </svg>\n              <span>Dados Abertos (CSV)</span>\n            </a>\n          </div>\n        </div>\n\n        <div class=\"overflow-x-auto\">\n          <table class=\"tabela-limpa\">\n            <thead>\n              <tr>\n                <th>Doc / Tipo</th>\n                <th>Data</th>\n                <th>Órgão / UG</th>\n                <th>Favorecido</th>\n                <th>Fase & Alerta</th>\n                <th class=\"text-right\">Valor Líquido</th>\n                <th class=\"text-right\">Proveniência</th>\n              </tr>\n            </thead>\n            <tbody id=\"tabelaDespesas\" class=\"divide-y divide-slate-100\">\n              <tr><td colspan=\"7\" class=\"py-4 text-center text-slate-400\">Carregando despesas granulares...</td></tr>\n            </tbody>\n          </table>\n        </div>\n\n        <!-- MICRO-GLOSSÁRIO CONTÁBIL & FISCAL (LEI 4.320/64) -->\n        <div class=\"pt-4 border-t border-slate-200 space-y-2.5\">\n          <div class=\"font-bold text-[#002776] uppercase tracking-wider text-[11px] flex items-center gap-1.5\">\n            <svg class=\"w-4 h-4 text-[#002776]\" viewBox=\"0 0 20 20\" fill=\"currentColor\">\n              <path d=\"M9 4.804A7.968 7.968 0 005.5 4c-1.255 0-2.443.29-3.5.804v10A7.969 7.969 0 015.5 14c1.669 0 3.218.51 4.5 1.385A7.962 7.962 0 0114.5 14c1.255 0 2.443.29-3.5.804v-10A7.968 7.968 0 0014.5 4c-1.255 0-2.443.29-3.5.804V12a1 1 0 11-2 0V4.804z\"/>\n            </svg>\n            <span>Micro-Glossário Cidadão: Entenda o Ciclo da Despesa</span>\n          </div>\n          <div class=\"grid grid-cols-1 md:grid-cols-4 gap-4 text-slate-800 text-xs\">\n            <div class=\"space-y-0.5\">\n              <strong class=\"text-amber-800 block\">1. Empenho (NE)</strong>\n              <p class=\"text-slate-600 text-[11px] leading-relaxed\">Reserva orçamentária do Estado para um fornecedor antes da compra.</p>\n            </div>\n            <div class=\"space-y-0.5\">\n              <strong class=\"text-blue-800 block\">2. Liquidação (NL)</strong>\n              <p class=\"text-slate-600 text-[11px] leading-relaxed\">Verificação do direito do credor após o serviço prestado ou produto entregue.</p>\n            </div>\n            <div class=\"space-y-0.5\">\n              <strong class=\"text-emerald-800 block\">3. Pagamento (OB)</strong>\n              <p class=\"text-slate-600 text-[11px] leading-relaxed\">Emissão da Ordem Bancária e débito da Conta Única para o favorecido.</p>\n            </div>\n            <div class=\"space-y-0.5\">\n              <strong class=\"text-amber-900 block\">4. Restos a Pagar (RAP)</strong>\n              <p class=\"text-slate-600 text-[11px] leading-relaxed\">Despesas empenhadas em anos anteriores e pagas no exercício atual.</p>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n\n  </main>\n\n  <!-- MODAL DE RASTREABILIDADE & AUDITORIA DE PROVENIÊNCIA -->\n  <div id=\"modalRastreabilidade\" class=\"fixed inset-0 bg-slate-900/50 backdrop-blur-xs z-50 hidden flex items-center justify-center p-4\">\n    <div class=\"bg-white border border-slate-200 rounded-2xl max-w-2xl w-full p-6 shadow-2xl relative space-y-4 max-h-[90vh] overflow-y-auto\">\n      <div class=\"flex items-center justify-between border-b border-slate-200 pb-3\">\n        <div class=\"flex items-center gap-2.5\">\n          <div class=\"w-8 h-8 rounded-lg bg-emerald-50 border border-emerald-200 flex items-center justify-center text-emerald-700\">\n            <svg class=\"w-4 h-4\" viewBox=\"0 0 20 20\" fill=\"currentColor\">\n              <path fill-rule=\"evenodd\" d=\"M10 1.944A11.954 11.954 0 012.166 5C2.056 5.649 2 6.319 2 7c0 5.225 3.34 9.67 8 11.317C14.66 16.67 18 12.225 18 7c0-.682-.057-1.35-.166-2.001A11.954 11.954 0 0110 1.944zM11 14a1 1 0 11-2 0 1 1 0 012 0zm0-7a1 1 0 10-2 0v3a1 1 0 102 0V7z\" clip-rule=\"evenodd\"/>\n            </svg>\n          </div>\n          <div>\n            <h3 class=\"text-base font-bold text-slate-900\">Contrato de Proveniência & Rastreabilidade</h3>\n            <p class=\"text-xs text-slate-600\">Origem oficial e conferência de integridade (Lei nº 12.527 / LAI)</p>\n          </div>\n        </div>\n        <button id=\"btnFecharModal\" class=\"text-slate-400 hover:text-slate-700 p-1 rounded-lg hover:bg-slate-100 transition-colors\" aria-label=\"Fechar modal\">\n          <svg class=\"w-5 h-5\" viewBox=\"0 0 20 20\" fill=\"currentColor\">\n            <path fill-rule=\"evenodd\" d=\"M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z\" clip-rule=\"evenodd\"/>\n          </svg>\n        </button>\n      </div>\n\n      <div class=\"space-y-3 text-xs\" id=\"conteudoModal\">\n        Carregando rastreabilidade...\n      </div>\n\n      <div class=\"border-t border-slate-200 pt-3 flex justify-end gap-3\" id=\"rodapeModal\">\n        <button id=\"btnFecharModalSecundario\" class=\"px-4 py-2 bg-white hover:bg-slate-50 text-slate-700 border border-slate-200 rounded-lg text-xs font-semibold transition-colors\">\n          Fechar\n        </button>\n      </div>\n    </div>\n  </div>\n\n  <!-- SCRIPT JS -->\n  <script src=\"/static/js/app.js\"></script>\n</body>\n</html>\n";
const APP_CSS = "/* ==========================================================================\n   TEMA SÓBRIO EM FUNDO BRANCO — TRANSPARÊNCIA PÚBLICA & AUDITORIA CÍVICA\n   Fundo Branco / Papel Neutro (#ffffff / #f8fafc), Azul Institucional (#002776),\n   Verde Bandeira (#00853b), Âmbar Ouro (#b45309)\n   REGRA FUNDAMENTAL: O Vermelho (#dc2626 / #991b1b) é ESTRITAMENTE EXCLUSIVO\n   para sinalizar \"ALERTA DE CORRUPÇÃO E IRREGULARIDADES GRAVES\"!\n   ========================================================================== */\n\n:root {\n  --font-sans: 'Public Sans', system-ui, -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n  --font-mono: 'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, Monaco, monospace;\n\n  /* Cores Neutras e Superfícies (Fundo Branco Sóbrio) */\n  --br-fundo: #f8fafc;\n  --br-superficie: #ffffff;\n  --br-superficie-subtil: #f1f5f9;\n  --br-borda: #e2e8f0;\n  --br-borda-hover: #cbd5e1;\n  --br-borda-foco: #002776;\n\n  /* Tipografia de Alto Contraste */\n  --br-texto-primario: #0f172a;\n  --br-texto-secundario: #334155;\n  --br-texto-apoio: #475569;\n\n  /* Cores Institucionais do Brasil */\n  --br-azul-institucional: #002776;\n  --br-azul-superficie: #eff6ff;\n  --br-azul-borda: #bfdbfe;\n  --br-azul-texto: #1d4ed8;\n\n  --br-verde-bandeira: #00853b;\n  --br-verde-hover: #006b2f;\n  --br-verde-superficie: #ecfdf5;\n  --br-verde-borda: #a7f3d0;\n  --br-verde-texto: #065f46;\n\n  --br-ouro-ambar: #b45309;\n  --br-ouro-superficie: #fffbeb;\n  --br-ouro-borda: #fde68a;\n\n  /* VERMELHO EXCLUSIVO: ALERTA DE CORRUPÇÃO & IRREGULARIDADES GRAVES */\n  --corrupcao-vermelho: #dc2626;\n  --corrupcao-vermelho-hover: #b91c1c;\n  --corrupcao-vermelho-superficie: #fef2f2;\n  --corrupcao-vermelho-borda: #fca5a5;\n  --corrupcao-vermelho-texto: #991b1b;\n}\n\n/* Reset e Escala Tipográfica Rigorosa */\n*, *::before, *::after {\n  box-sizing: border-box;\n}\n\nbody {\n  font-family: var(--font-sans);\n  font-size: 0.875rem; /* 14px */\n  line-height: 1.5;\n  background-color: var(--br-fundo);\n  color: var(--br-texto-primario);\n  margin: 0;\n  padding: 0;\n  -webkit-font-smoothing: antialiased;\n  -moz-osx-font-smoothing: grayscale;\n}\n\nh1 {\n  font-size: 1.875rem; /* 30px */\n  font-weight: 800;\n  line-height: 1.2;\n  letter-spacing: -0.025em;\n  color: var(--br-texto-primario);\n  margin: 0;\n}\n\nh2 {\n  font-size: 1.375rem; /* 22px */\n  font-weight: 800;\n  line-height: 1.25;\n  letter-spacing: -0.02em;\n  color: var(--br-texto-primario);\n  margin: 0;\n}\n\nh3 {\n  font-size: 1.125rem; /* 18px */\n  font-weight: 700;\n  line-height: 1.35;\n  letter-spacing: -0.01em;\n  color: var(--br-texto-primario);\n  margin: 0;\n}\n\nh4 {\n  font-size: 0.9375rem; /* 15px */\n  font-weight: 600;\n  line-height: 1.4;\n  color: var(--br-texto-primario);\n  margin: 0;\n}\n\n/* Custom Scrollbars Sóbrias */\n::-webkit-scrollbar {\n  width: 8px;\n  height: 8px;\n}\n::-webkit-scrollbar-track {\n  background: var(--br-fundo);\n}\n::-webkit-scrollbar-thumb {\n  background: #cbd5e1;\n  border-radius: 4px;\n}\n::-webkit-scrollbar-thumb:hover {\n  background: var(--br-verde-bandeira);\n}\n\n/* Seleção de Texto e Focus Rings */\n::selection {\n  background-color: var(--br-verde-bandeira);\n  color: #ffffff;\n}\n\n:focus-visible {\n  outline: 2px solid var(--br-azul-institucional);\n  outline-offset: 2px;\n}\n\n/* Numerais Tabulares e Fontes Periciais */\n.tabular-nums {\n  font-variant-numeric: tabular-nums;\n}\n\n/* Cartões Analíticos em Fundo Branco */\n.card-analitico {\n  background-color: var(--br-superficie);\n  border: 1px solid var(--br-borda);\n  border-radius: 12px;\n  padding: 1.25rem;\n  box-shadow: 0 1px 3px 0 rgba(0, 0, 0, 0.05), 0 1px 2px -1px rgba(0, 0, 0, 0.05);\n}\n\n/* Tabelas Limpas em Largura Total */\n.tabela-limpa {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: 0.8125rem;\n}\n\n.tabela-limpa th {\n  padding: 0.75rem 1rem;\n  text-align: left;\n  font-size: 0.6875rem;\n  font-weight: 700;\n  letter-spacing: 0.05em;\n  text-transform: uppercase;\n  color: var(--br-texto-apoio);\n  background-color: var(--br-superficie-subtil);\n  border-bottom: 1px solid var(--br-borda);\n  white-space: nowrap;\n}\n\n.tabela-limpa td {\n  padding: 0.75rem 1rem;\n  border-bottom: 1px solid #f1f5f9;\n  vertical-align: middle;\n}\n\n.tabela-limpa tr:hover td {\n  background-color: #f8fafc;\n}\n\n/* Abas de Navegação */\n.tab-btn {\n  border-bottom: 2px solid transparent;\n  color: var(--br-texto-apoio);\n  padding: 0.625rem 1rem;\n  font-size: 0.8125rem;\n  font-weight: 600;\n  transition: all 0.15s ease-in-out;\n}\n\n.tab-btn:hover {\n  color: var(--br-texto-primario);\n  background-color: var(--br-superficie-subtil);\n}\n\n.tab-btn.active {\n  border-bottom-color: var(--br-azul-institucional);\n  color: var(--br-azul-institucional);\n  background-color: var(--br-superficie);\n}\n\n.tab-btn-corrupcao {\n  color: var(--corrupcao-vermelho-texto);\n  background-color: var(--corrupcao-vermelho-superficie);\n}\n\n.tab-btn-corrupcao:hover {\n  background-color: #fee2e2;\n  color: var(--corrupcao-vermelho-texto);\n}\n\n.tab-btn-corrupcao.active {\n  border-bottom-color: var(--corrupcao-vermelho) !important;\n  color: var(--corrupcao-vermelho-texto) !important;\n  background-color: var(--corrupcao-vermelho-superficie) !important;\n}\n\n/* ==========================================================================\n   ALERTA DE CORRUPÇÃO EM FUNDO CLARO — DESTAQUE COM MÁXIMA GRAVIDADE\n   ========================================================================== */\n.card-corrupcao-alerta {\n  background-color: var(--corrupcao-vermelho-superficie);\n  border: 1px solid var(--corrupcao-vermelho-borda);\n  border-radius: 12px;\n  padding: 1.25rem;\n  box-shadow: 0 1px 3px 0 rgba(220, 38, 38, 0.08);\n  transition: transform 0.15s ease, background-color 0.15s ease, box-shadow 0.15s ease;\n}\n\n.card-corrupcao-alerta:hover {\n  background-color: #fee2e2;\n  box-shadow: 0 4px 12px -2px rgba(220, 38, 38, 0.15);\n  transform: translateY(-1px);\n}\n\n.badge-corrupcao {\n  background-color: #fee2e2;\n  color: var(--corrupcao-vermelho-texto);\n  border: 1px solid var(--corrupcao-vermelho-borda);\n  font-family: var(--font-mono);\n  font-weight: 700;\n  text-transform: uppercase;\n  letter-spacing: 0.05em;\n  padding: 3px 8px;\n  border-radius: 9999px;\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n}\n\n/* Linha da Tabela sob Alerta de Corrupção */\n.linha-corrupcao {\n  background-color: #fef2f2 !important;\n  box-shadow: inset 0 0 0 1px var(--corrupcao-vermelho-borda);\n}\n\n.linha-corrupcao:hover {\n  background-color: #fee2e2 !important;\n}\n\n/* Badges das Fases Orçamentárias em Fundo Claro */\n.badge-fase {\n  padding: 2px 8px;\n  border-radius: 9999px;\n  font-size: 10px;\n  font-weight: 700;\n  font-family: var(--font-mono);\n  text-transform: uppercase;\n  letter-spacing: 0.05em;\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n}\n\n.badge-pagamento {\n  background-color: #ecfdf5;\n  color: #065f46;\n  border: 1px solid #a7f3d0;\n}\n\n.badge-liquidacao {\n  background-color: #eff6ff;\n  color: #1d4ed8;\n  border: 1px solid #bfdbfe;\n}\n\n.badge-empenho {\n  background-color: #fffbeb;\n  color: #b45309;\n  border: 1px solid #fde68a;\n}\n\n.badge-rap {\n  background-color: #fefce8;\n  color: #854d0e;\n  border: 1px solid #fef08a;\n}\n\n.badge-repasse {\n  background-color: #f0f9ff;\n  color: #0369a1;\n  border: 1px solid #bae6fd;\n}\n";
const APP_JS = "/**\n * Plataforma Transparência Brasil - Cliente Frontend\n * Tema: Sóbrio em Fundo Branco (Papel Neutro, Azul Institucional, Verde Bandeira, Âmbar Ouro)\n * Regra: Vermelho EXCLUSIVAMENTE para sinalizar indícios de Corrupção e Irregularidades Graves.\n */\n\n// Formatador Monetário Brasileiro (BRL)\nconst formatarMoeda = (valor) => {\n  return new Intl.NumberFormat('pt-BR', {\n    style: 'currency',\n    currency: 'BRL',\n    maximumFractionDigits: 2,\n  }).format(valor || 0);\n};\n\nconst formatarNumero = (valor) => {\n  return new Intl.NumberFormat('pt-BR').format(valor || 0);\n};\n\n// Ícone SVG de Link Externo\nconst svgExternalLink = `\n  <svg class=\"w-3 h-3 inline-block ml-1 opacity-70\" viewBox=\"0 0 20 20\" fill=\"currentColor\">\n    <path d=\"M11 3a1 1 0 100 2h2.586l-6.293 6.293a1 1 0 101.414 1.414L15 6.414V9a1 1 0 102 0V4a1 1 0 00-1-1h-5z\"/>\n    <path d=\"M5 5a2 2 0 00-2 2v8a2 2 0 002 2h8a2 2 0 002-2v-3a1 1 0 10-2 0v3H5V7h3a1 1 0 000-2H5z\"/>\n  </svg>\n`;\n\n// Ícone SVG de Alerta de Corrupção\nconst svgAlertTriangle = `\n  <svg class=\"w-3.5 h-3.5 text-red-600 shrink-0 inline-block\" viewBox=\"0 0 20 20\" fill=\"currentColor\">\n    <path fill-rule=\"evenodd\" d=\"M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z\" clip-rule=\"evenodd\"/>\n  </svg>\n`;\n\n// Estado da Aplicação\nconst state = {\n  ano: 2026,\n  modo: 'cidadao', // 'cidadao' | 'auditor'\n  resumo: null,\n  alertasCorrupcao: [],\n};\n\n// Inicialização\ndocument.addEventListener('DOMContentLoaded', () => {\n  inicializarEventos();\n  carregarDadosCompletos();\n});\n\nfunction inicializarEventos() {\n  // Alternador de Modo\n  const btnCidadao = document.getElementById('btnModoCidadao');\n  const btnAuditor = document.getElementById('btnModoAuditor');\n  const funilSection = document.getElementById('funilOrcamentarioSection');\n\n  btnCidadao.addEventListener('click', () => {\n    state.modo = 'cidadao';\n    btnCidadao.className = 'px-3 py-1.5 bg-slate-900 text-white font-bold transition-colors';\n    btnAuditor.className = 'px-3 py-1.5 bg-white text-slate-600 hover:text-slate-900 transition-colors';\n    funilSection.classList.add('hidden');\n  });\n\n  btnAuditor.addEventListener('click', () => {\n    state.modo = 'auditor';\n    btnAuditor.className = 'px-3 py-1.5 bg-[#002776] text-white font-bold transition-colors';\n    btnCidadao.className = 'px-3 py-1.5 bg-white text-slate-600 hover:text-slate-900 transition-colors';\n    funilSection.classList.remove('hidden');\n  });\n\n  // Botão direto para o Radar de Corrupção no topo\n  document.getElementById('btnIrParaRadar').addEventListener('click', () => {\n    navegarParaAba('tabRadarCorrupcao');\n  });\n\n  // Abas de Navegação\n  const tabBtns = document.querySelectorAll('.tab-btn');\n  tabBtns.forEach((btn) => {\n    btn.addEventListener('click', () => {\n      const targetTab = btn.getAttribute('data-tab');\n      navegarParaAba(targetTab);\n    });\n  });\n\n  // Botão Sincronizar Fontes\n  document.getElementById('btnExecutarPipeline').addEventListener('click', async () => {\n    const btn = document.getElementById('btnExecutarPipeline');\n    btn.disabled = true;\n    btn.innerHTML = `\n      <svg class=\"animate-spin inline-block mr-1.5 w-3.5 h-3.5 text-slate-700\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\">\n        <circle class=\"opacity-25\" cx=\"12\" cy=\"12\" r=\"10\" stroke=\"currentColor\" stroke-width=\"4\"></circle>\n        <path class=\"opacity-75\" fill=\"currentColor\" d=\"M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z\"></path>\n      </svg>\n      Sincronizando...\n    `;\n    try {\n      await fetch(`/api/v1/pipeline/executar?ano=${state.ano}`, { method: 'POST' });\n      await carregarDadosCompletos();\n      console.log('Fontes sincronizadas com sucesso.');\n    } catch (e) {\n      console.error('Erro ao sincronizar:', e);\n    } finally {\n      btn.disabled = false;\n      btn.innerHTML = '<span class=\"inline-block w-2 h-2 rounded-full bg-[#00853b]\"></span> Sincronizar';\n    }\n  });\n\n  // Busca Granular\n  document.getElementById('btnBuscar').addEventListener('click', () => {\n    const termo = document.getElementById('campoBusca').value;\n    carregarDespesasGranulares(termo);\n  });\n\n  document.getElementById('campoBusca').addEventListener('keyup', (e) => {\n    if (e.key === 'Enter') {\n      carregarDespesasGranulares(e.target.value);\n    }\n  });\n\n  const checkCorrupcao = document.getElementById('checkApenasCorrupcao');\n  if (checkCorrupcao) {\n    checkCorrupcao.addEventListener('change', () => {\n      const termo = document.getElementById('campoBusca').value;\n      carregarDespesasGranulares(termo);\n    });\n  }\n\n  // Fechar Modal\n  document.getElementById('btnFecharModal').addEventListener('click', fecharModal);\n  document.getElementById('btnFecharModalSecundario').addEventListener('click', fecharModal);\n}\n\nfunction navegarParaAba(targetTab) {\n  const tabBtns = document.querySelectorAll('.tab-btn');\n  tabBtns.forEach((b) => {\n    const isCorrupcao = b.getAttribute('data-tab') === 'tabRadarCorrupcao';\n    b.classList.remove('active', 'border-[#002776]', 'text-[#002776]', 'bg-white', 'border-red-600', 'text-red-700', 'font-bold');\n    if (!isCorrupcao) {\n      b.classList.add('border-transparent', 'text-slate-600');\n    }\n  });\n\n  const activeBtn = document.querySelector(`.tab-btn[data-tab=\"${targetTab}\"]`);\n  if (activeBtn) {\n    if (targetTab === 'tabRadarCorrupcao') {\n      activeBtn.classList.add('active', 'border-red-600', 'text-red-700', 'bg-red-50', 'font-bold');\n    } else {\n      activeBtn.classList.add('active', 'border-[#002776]', 'text-[#002776]', 'bg-white', 'font-bold');\n      activeBtn.classList.remove('border-transparent', 'text-slate-600');\n    }\n  }\n\n  document.querySelectorAll('.tab-content').forEach((sec) => sec.classList.add('hidden'));\n  const targetSec = document.getElementById(targetTab);\n  if (targetSec) {\n    targetSec.classList.remove('hidden');\n  }\n}\n\nasync function carregarDadosCompletos() {\n  await carregarResumoNacional();\n  await Promise.all([\n    carregarAlertasCorrupcao(),\n    carregarEconomiaPlanoVsRealidade(),\n    carregarOrgaos(),\n    carregarFuncoes(),\n    carregarMunicipios(),\n    carregarContratosPNCP(),\n    carregarTopFornecedores(),\n    carregarDespesasGranulares(),\n  ]);\n}\n\n// 1. Resumo Nacional e Funil\nasync function carregarResumoNacional() {\n  try {\n    const res = await fetch(`/api/v1/resumo?ano=${state.ano}`);\n    const data = await res.json();\n    state.resumo = data;\n\n    // Atualiza KPIs\n    document.getElementById('kpiGastoEfetivo').textContent = formatarMoeda(data.gasto_efetivo_nacional);\n    document.getElementById('kpiTotalPago').textContent = formatarMoeda(data.total_pago_liquido);\n    document.getElementById('kpiRapPagos').textContent = formatarMoeda(data.total_restos_a_pagar_pagos);\n    document.getElementById('kpiTransferencias').textContent = formatarMoeda(data.total_transferencias_intergovernamentais);\n\n    // KPI VERMELHO EXCLUSIVO: ALERTA DE CORRUPÇÃO\n    const totalCorrupcao = data.total_alertas_corrupcao || 0;\n    const valorCorrupcao = data.valor_sob_alerta_corrupcao || 0;\n\n    document.getElementById('kpiTotalAlertasCorrupcao').textContent = `${totalCorrupcao} Casos`;\n    document.getElementById('kpiValorCorrupcao').textContent = formatarMoeda(valorCorrupcao);\n    document.getElementById('headerQtdCorrupcao').textContent = `${totalCorrupcao} Indícios`;\n    const tabQtd = document.getElementById('tabQtdCorrupcao');\n    if (tabQtd) tabQtd.textContent = `${totalCorrupcao} Casos`;\n\n    // Atualiza Funil Orçamentário\n    document.getElementById('funilEmpenho').textContent = formatarMoeda(data.total_empenhado_liquido);\n    document.getElementById('funilLiquidado').textContent = formatarMoeda(data.total_liquidado);\n    document.getElementById('funilPago').textContent = formatarMoeda(data.total_pago_liquido);\n    document.getElementById('funilRepasses').textContent = formatarMoeda(data.total_transferencias_intergovernamentais);\n  } catch (err) {\n    console.error('Erro ao carregar resumo nacional:', err);\n  }\n}\n\n// 2. RADAR ANTI-CORRUPÇÃO (DESTAQUE VERMELHO EM FUNDO BRANCO)\nasync function carregarAlertasCorrupcao() {\n  const container = document.getElementById('gridCasosCorrupcao');\n  try {\n    const res = await fetch(`/api/v1/alertas-corrupcao?ano=${state.ano}`);\n    const alertas = await res.json();\n    state.alertasCorrupcao = alertas;\n\n    if (!alertas || alertas.length === 0) {\n      container.innerHTML = '<div class=\"col-span-3 py-6 text-center text-xs text-emerald-700\">Nenhum indício grave registrado para o exercício.</div>';\n      return;\n    }\n\n    // Ordena rigorosamente pelos valores mais elevados primeiro\n    alertas.sort((x, y) => (Number(y.valor_liquido_reais) || 0) - (Number(x.valor_liquido_reais) || 0));\n\n    container.innerHTML = alertas.map((a, idx) => {\n      let badgeRisco = 'EMPRESA INIDÔNEA (CEIS)';\n      if (a.tipo_risco === 'SOBREPRECO_ATIPICO') badgeRisco = 'SOBREPREÇO / DESVIO FISCAL';\n      if (a.tipo_risco === 'FRACIONAMENTO_ILEGAL') badgeRisco = 'FRACIONAMENTO / RETENÇÃO';\n\n      return `\n        <div class=\"bg-white border border-red-200 hover:border-red-400 rounded-xl p-4 flex flex-col justify-between space-y-3 transition-all shadow-xs\">\n          <div class=\"space-y-2\">\n            <div class=\"flex items-center justify-between text-[11px]\">\n              <span class=\"badge-corrupcao\">\n                ${svgAlertTriangle}\n                <span>#${idx + 1} • ${badgeRisco}</span>\n              </span>\n              <span class=\"text-red-700 font-mono text-[10px] tabular-nums font-semibold\">${a.data_evento}</span>\n            </div>\n\n            <div class=\"pt-1\">\n              <div class=\"text-[10px] uppercase tracking-wider text-red-700 font-bold\">Valor sob Suspeita</div>\n              <div class=\"text-xl font-black font-mono tabular-nums text-red-700\">${formatarMoeda(a.valor_liquido_reais)}</div>\n            </div>\n\n            <p class=\"text-xs text-slate-700 leading-relaxed font-medium\">\n              ${a.motivo_corrupcao}\n            </p>\n\n            <div class=\"text-[11px] space-y-0.5 text-slate-600\">\n              <div class=\"font-bold text-slate-900\">${a.orgao}</div>\n              <div class=\"text-slate-500 line-clamp-1\">${a.unidade_gestora}</div>\n              <div class=\"font-mono text-[10px] text-amber-800 font-semibold pt-1\">\n                Credor: ${a.favorecido_nome} (${a.favorecido_documento})\n              </div>\n            </div>\n          </div>\n\n          <div class=\"border-t border-red-100 pt-3 flex items-center justify-between\">\n            <span class=\"font-mono text-[11px] text-red-800 font-bold tabular-nums\">${a.tipo_documento} nº ${a.numero_documento}</span>\n            <button onclick=\"abrirModalRastreabilidade('${a.numero_documento}')\" class=\"px-3 py-1.5 bg-[#dc2626] hover:bg-[#b91c1c] text-white rounded-lg text-xs font-bold transition-all shadow-xs\">\n              Auditar\n            </button>\n          </div>\n        </div>\n      `;\n    }).join('');\n  } catch (err) {\n    container.innerHTML = '<div class=\"col-span-3 py-4 text-center text-xs text-red-600\">Erro ao carregar radar anti-corrupção.</div>';\n  }\n}\n\n// 2B. ECONOMIA: PLANO DE GOVERNO VS. REALIDADE EXECUTADA (BCB + SICONFI UNIÃO)\nasync function carregarEconomiaPlanoVsRealidade() {\n  const gridMacro = document.getElementById('gridIndicadoresEconomia');\n  const tbodySetorial = document.getElementById('tabelaEconomiaSetorial');\n  if (!gridMacro || !tbodySetorial) return;\n\n  try {\n    const res = await fetch(`/api/v1/economia/plano-vs-realidade?ano=${state.ano}`);\n    const data = await res.json();\n\n    // Renderiza Indicadores Macroeconômicos (BCB SGS + Tesouro)\n    const macro = data.indicadores_macro || [];\n    gridMacro.innerHTML = macro.map((m) => `\n      <div class=\"bg-white border border-red-200 rounded-xl p-4 flex flex-col justify-between space-y-3 shadow-xs\">\n        <div class=\"space-y-2\">\n          <div class=\"flex items-center justify-between text-[10px]\">\n            <span class=\"badge-corrupcao\">${svgAlertTriangle}<span>DESVIO DE META</span></span>\n            <span class=\"font-mono text-slate-600 tabular-nums\">${m.data_referencia}</span>\n          </div>\n          <h4 class=\"text-xs font-bold text-slate-900 leading-snug\">${m.indicador}</h4>\n          <div class=\"space-y-1 pt-1 text-xs\">\n            <div class=\"flex items-center justify-between\">\n              <span class=\"text-slate-600\">Plano Prometido:</span>\n              <span class=\"font-mono font-semibold text-emerald-800 tabular-nums\">${m.plano_prometido}</span>\n            </div>\n            <div class=\"flex items-center justify-between\">\n              <span class=\"text-slate-600\">Realidade em Prática:</span>\n              <span class=\"font-mono font-black text-red-700 tabular-nums text-sm\">${m.realidade_pratica}</span>\n            </div>\n            <div class=\"text-[11px] font-mono font-bold text-red-800 pt-0.5\">\n              ${m.desvio_critico}\n            </div>\n          </div>\n          <p class=\"text-[11px] text-slate-700 leading-relaxed pt-1\">\n            ${m.impacto_real}\n          </p>\n        </div>\n        <div class=\"border-t border-red-100 pt-2 flex items-center justify-between text-[10px]\">\n          <span class=\"font-mono text-slate-600 truncate max-w-[180px]\">${m.fonte_oficial}</span>\n          <a href=\"${m.url_comprovante}\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-[#002776] font-bold hover:underline inline-flex items-center\">\n            Fonte Oficial ${svgExternalLink}\n          </a>\n        </div>\n      </div>\n    `).join('');\n\n    // Renderiza Comparativo Setorial da União (Ordenado pelos Valores Mais Elevados)\n    const setores = (data.comparativo_setorial || []).sort(\n      (a, b) => (Number(b.orcamento_planejado_reais) || 0) - (Number(a.orcamento_planejado_reais) || 0)\n    );\n\n    tbodySetorial.innerHTML = setores.map((s) => {\n      const linhaClasse = s.alerta_grave ? 'linha-corrupcao' : 'hover:bg-slate-50';\n      const corPct = s.alerta_grave ? 'text-red-700 font-black' : 'text-emerald-800 font-bold';\n      return `\n        <tr class=\"${linhaClasse} transition-colors\">\n          <td class=\"py-3 px-4\">\n            <div class=\"font-bold text-slate-900\">${s.funcao}</div>\n            <div class=\"text-[11px] text-slate-600\">${s.promessa_plano}</div>\n          </td>\n          <td class=\"py-3 px-4 text-right font-mono tabular-nums font-semibold text-slate-900\">\n            ${formatarMoeda(s.orcamento_planejado_reais)}\n          </td>\n          <td class=\"py-3 px-4 text-right font-mono tabular-nums font-bold text-emerald-800\">\n            ${formatarMoeda(s.executado_efetivo_reais)}\n          </td>\n          <td class=\"py-3 px-4 text-right font-mono tabular-nums ${corPct}\">\n            ${s.taxa_execucao_pct.toFixed(1)}%\n          </td>\n          <td class=\"py-3 px-4 text-right font-mono tabular-nums font-bold ${s.alerta_grave ? 'text-red-700' : 'text-amber-800'}\">\n            ${formatarMoeda(s.travado_restos_a_pagar_reais)}\n          </td>\n          <td class=\"py-3 px-4 text-xs ${s.alerta_grave ? 'text-red-800 font-semibold' : 'text-slate-700'}\">\n            ${s.diagnostico_auditoria}\n          </td>\n        </tr>\n      `;\n    }).join('');\n  } catch (err) {\n    console.error('Erro ao carregar economia plano vs realidade:', err);\n  }\n}\n\n// 3. Ranking de Ministérios\nasync function carregarOrgaos() {\n  const container = document.getElementById('listaOrgaos');\n  try {\n    const res = await fetch(`/api/v1/orgaos?ano=${state.ano}&limite=8`);\n    const orgaos = await res.json();\n\n    if (!orgaos || orgaos.length === 0) {\n      container.innerHTML = '<div class=\"py-4 text-center text-xs text-slate-400\">Nenhum órgão registrado.</div>';\n      return;\n    }\n\n    container.innerHTML = orgaos.map((org, idx) => `\n      <div class=\"py-3 flex items-center justify-between text-xs hover:bg-slate-50 px-2 rounded-lg transition-colors\">\n        <div class=\"flex items-center gap-3\">\n          <span class=\"w-6 h-6 rounded-full bg-slate-100 border border-slate-200 flex items-center justify-center font-bold text-[#002776] text-[11px] font-mono tabular-nums\">\n            ${idx + 1}\n          </span>\n          <div>\n            <div class=\"font-bold text-slate-900\">${org.nome}</div>\n            <div class=\"text-[11px] text-slate-500 flex items-center gap-2\">\n              <span>Cód: ${org.codigo}</span>\n              ${org.total_repasses > 0 ? `<span class=\"text-sky-700 font-medium\">• Repasses: ${formatarMoeda(org.total_repasses)}</span>` : ''}\n            </div>\n          </div>\n        </div>\n        <div class=\"text-right\">\n          <div class=\"font-bold font-mono tabular-nums text-emerald-800\">${formatarMoeda(org.total_pago)}</div>\n          <div class=\"text-[10px] text-slate-400 tabular-nums\">${org.qtd_documentos} docs</div>\n        </div>\n      </div>\n    `).join('');\n  } catch (err) {\n    container.innerHTML = '<div class=\"py-4 text-center text-xs text-red-600\">Erro ao carregar ministérios.</div>';\n  }\n}\n\n// 4. Funções de Governo\nasync function carregarFuncoes() {\n  const container = document.getElementById('listaFuncoes');\n  try {\n    const res = await fetch(`/api/v1/funcoes?ano=${state.ano}`);\n    const funcoes = await res.json();\n\n    container.innerHTML = funcoes.map((f) => `\n      <div class=\"space-y-1 text-xs\">\n        <div class=\"flex justify-between items-center text-slate-700\">\n          <span class=\"font-semibold text-slate-900\">${f.funcao}</span>\n          <span class=\"font-mono tabular-nums text-slate-900 font-bold\">${formatarMoeda(f.total_reais)} <span class=\"text-[#002776] text-[11px]\">(${f.percentual}%)</span></span>\n        </div>\n        <div class=\"w-full bg-slate-100 rounded-full h-2 overflow-hidden border border-slate-200\">\n          <div class=\"bg-[#00853b] h-2 rounded-full\" style=\"width: ${Math.min(100, f.percentual)}%\"></div>\n        </div>\n      </div>\n    `).join('');\n  } catch (err) {\n    container.innerHTML = '<div class=\"py-4 text-center text-xs text-red-600\">Erro ao carregar funções.</div>';\n  }\n}\n\n// 5. Estados e Municípios (SICONFI)\nasync function carregarMunicipios() {\n  const tbody = document.getElementById('tabelaMunicipios');\n  try {\n    const res = await fetch(`/api/v1/siconfi/municipios?ano=${state.ano}`);\n    const munics = await res.json();\n\n    tbody.innerHTML = munics.map((m) => `\n      <tr class=\"hover:bg-slate-50 transition-colors\">\n        <td class=\"py-3 px-4 font-semibold text-slate-900\">\n          ${m.municipio} - <span class=\"text-[#002776] font-bold\">${m.uf}</span>\n          <div class=\"text-[10px] text-slate-500 font-mono tabular-nums\">IBGE: ${m.codigo_ibge}</div>\n        </td>\n        <td class=\"py-3 px-4 font-mono tabular-nums text-slate-700 text-right\">${formatarNumero(m.populacao_ibge)} hab.</td>\n        <td class=\"py-3 px-4 font-mono tabular-nums font-bold text-emerald-800 text-right\">${formatarMoeda(m.gasto_per_capita)} / hab</td>\n        <td class=\"py-3 px-4 font-mono tabular-nums text-slate-600 text-right\">${formatarMoeda(m.gasto_saude)}</td>\n        <td class=\"py-3 px-4 font-mono tabular-nums text-slate-600 text-right\">${formatarMoeda(m.gasto_educacao)}</td>\n        <td class=\"py-3 px-4 font-mono tabular-nums font-semibold text-slate-900 text-right\">${formatarMoeda(m.despesa_paga)}</td>\n        <td class=\"py-3 px-4 text-right\">\n          <a href=\"${m.fonte_url}\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"px-2.5 py-1 bg-slate-100 hover:bg-slate-200 text-[#002776] border border-slate-200 rounded text-[11px] font-semibold transition-colors inline-flex items-center\">\n            SICONFI ${svgExternalLink}\n          </a>\n        </td>\n      </tr>\n    `).join('');\n  } catch (err) {\n    tbody.innerHTML = '<tr><td colspan=\"7\" class=\"py-4 text-center text-xs text-red-600\">Erro ao carregar municípios.</td></tr>';\n  }\n}\n\n// 6. Contratos do PNCP\nasync function carregarContratosPNCP() {\n  const container = document.getElementById('cardsContratos');\n  try {\n    const res = await fetch(`/api/v1/pncp/contratos?ano=${state.ano}`);\n    const contratos = await res.json();\n\n    container.innerHTML = contratos.map((c) => `\n      <div class=\"bg-white border border-slate-200 rounded-xl p-4 flex flex-col justify-between space-y-3 hover:border-slate-300 transition-all shadow-xs\">\n        <div class=\"space-y-2\">\n          <div class=\"flex items-center justify-between text-[11px]\">\n            <span class=\"px-2 py-0.5 rounded bg-slate-100 text-[#002776] border border-slate-200 font-mono tabular-nums font-semibold\">\n              Contrato nº ${c.numero_contrato}\n            </span>\n            <span class=\"text-slate-500 font-mono text-[10px] tabular-nums\">${c.vigencia_inicio} a ${c.vigencia_fim}</span>\n          </div>\n          <h4 class=\"text-xs font-semibold text-slate-900 line-clamp-2 leading-snug\">\n            ${c.objeto}\n          </h4>\n          <div class=\"text-[11px] text-slate-600\">\n            <span class=\"block text-slate-900 font-medium\">${c.orgao_nome}</span>\n            <span class=\"block text-amber-800 font-mono text-[10px]\">Credor: ${c.fornecedor_razao_social}</span>\n          </div>\n        </div>\n\n        <div class=\"border-t border-slate-100 pt-2 flex items-center justify-between\">\n          <div>\n            <div class=\"text-[10px] uppercase text-slate-500\">Homologado</div>\n            <div class=\"text-sm font-bold font-mono tabular-nums text-emerald-800\">${formatarMoeda(c.valor_homologado)}</div>\n          </div>\n          <a href=\"${c.url_oficial}\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"px-2.5 py-1 bg-slate-100 hover:bg-slate-200 text-[#002776] border border-slate-200 rounded text-[11px] font-bold transition-colors inline-flex items-center\">\n            Ver PNCP ${svgExternalLink}\n          </a>\n        </div>\n      </div>\n    `).join('');\n  } catch (err) {\n    container.innerHTML = '<div class=\"col-span-3 py-4 text-center text-xs text-red-600\">Erro ao carregar contratos do PNCP.</div>';\n  }\n}\n\n// 7. Top Fornecedores\nasync function carregarTopFornecedores() {\n  const tbody = document.getElementById('tabelaFornecedores');\n  try {\n    const res = await fetch(`/api/v1/fornecedores?ano=${state.ano}&limite=10`);\n    const fornecedores = await res.json();\n\n    tbody.innerHTML = fornecedores.map((f) => `\n      <tr class=\"hover:bg-slate-50 transition-colors\">\n        <td class=\"py-3 px-4 font-semibold text-slate-900\">${f.nome}</td>\n        <td class=\"py-3 px-4 font-mono tabular-nums text-slate-600\">${f.documento}</td>\n        <td class=\"py-3 px-4\">\n          <span class=\"px-2 py-0.5 rounded text-[10px] font-semibold bg-slate-100 text-slate-700 border border-slate-200\">\n            ${f.tipo}\n          </span>\n        </td>\n        <td class=\"py-3 px-4 text-right font-mono tabular-nums text-slate-700\">${f.qtd_pagamentos}</td>\n        <td class=\"py-3 px-4 text-right font-mono tabular-nums font-bold text-emerald-800\">${formatarMoeda(f.total_recebido)}</td>\n        <td class=\"py-3 px-4 text-right\">\n          <a href=\"${f.url_comprovante}\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"px-2.5 py-1 bg-slate-100 hover:bg-slate-200 text-[#002776] border border-slate-200 rounded text-[11px] font-semibold transition-colors inline-flex items-center\">\n            Consultar ${svgExternalLink}\n          </a>\n        </td>\n      </tr>\n    `).join('');\n  } catch (err) {\n    tbody.innerHTML = '<tr><td colspan=\"6\" class=\"py-4 text-center text-xs text-red-600\">Erro ao carregar fornecedores.</td></tr>';\n  }\n}\n\n// 8. Despesas Granulares com Destaque Vermelho em Corrupção\nasync function carregarDespesasGranulares(termo = '') {\n  const tbody = document.getElementById('tabelaDespesas');\n  const checkCorrupcao = document.getElementById('checkApenasCorrupcao');\n  const apenasCorrupcao = checkCorrupcao ? checkCorrupcao.checked : false;\n\n  // Atualiza link de exportação de dados abertos CSV\n  const linkCsv = document.getElementById('linkExportarCsv');\n  if (linkCsv) {\n    linkCsv.href = `/api/v1/exportar/despesas.csv?ano=${state.ano}&apenas_corrupcao=${apenasCorrupcao}`;\n  }\n\n  try {\n    let url = `/api/v1/despesas?ano=${state.ano}&limite=50&apenas_corrupcao=${apenasCorrupcao}`;\n    if (termo) url += `&busca=${encodeURIComponent(termo)}`;\n\n    const res = await fetch(url);\n    const data = await res.json();\n\n    if (!data.itens || data.itens.length === 0) {\n      tbody.innerHTML = '<tr><td colspan=\"7\" class=\"py-4 text-center text-xs text-slate-500\">Nenhum registro encontrado para a busca.</td></tr>';\n      return;\n    }\n\n    tbody.innerHTML = data.itens.map((d) => {\n      let badgeClass = 'badge-pagamento';\n      if (d.fase_despesa === 'EMPENHO') badgeClass = 'badge-empenho';\n      if (d.fase_despesa === 'LIQUIDACAO') badgeClass = 'badge-liquidacao';\n      if (d.fase_despesa === 'RESTOS_A_PAGAR_PAGOS') badgeClass = 'badge-rap';\n\n      // Linha em Vermelho se houver Alerta de Corrupção\n      const linhaClasse = d.alerta_corrupcao ? 'linha-corrupcao' : 'hover:bg-slate-50';\n\n      return `\n        <tr class=\"${linhaClasse} transition-colors\">\n          <td class=\"py-3 px-4\">\n            <span class=\"font-mono tabular-nums font-bold text-slate-900\">${d.numero_documento}</span>\n            <div class=\"text-[10px] text-slate-500 font-mono\">${d.tipo_documento}</div>\n          </td>\n          <td class=\"py-3 px-4 font-mono tabular-nums text-slate-600 text-[11px]\">${d.data_evento}</td>\n          <td class=\"py-3 px-4\">\n            <div class=\"font-semibold text-slate-900\">${d.orgao}</div>\n            <div class=\"text-[11px] text-slate-500 line-clamp-1\">${d.unidade_gestora}</div>\n          </td>\n          <td class=\"py-3 px-4\">\n            <div class=\"font-semibold text-slate-900\">${d.favorecido_nome}</div>\n            <div class=\"text-[11px] text-amber-800 font-mono tabular-nums\">${d.favorecido_documento}</div>\n          </td>\n          <td class=\"py-3 px-4\">\n            <div class=\"flex items-center gap-1.5 flex-wrap\">\n              <span class=\"badge-fase ${badgeClass}\">${d.fase_despesa}</span>\n              ${d.is_transferencia ? '<span class=\"badge-fase badge-repasse\">REPASSE</span>' : ''}\n              ${d.alerta_corrupcao ? `\n                <span class=\"badge-corrupcao text-[10px] font-mono\">\n                  ${svgAlertTriangle}\n                  <span>CORRUPÇÃO / RISCO</span>\n                </span>\n              ` : ''}\n            </div>\n          </td>\n          <td class=\"py-3 px-4 text-right font-mono tabular-nums font-bold ${d.alerta_corrupcao ? 'text-red-700' : 'text-emerald-800'}\">\n            ${formatarMoeda(d.valor_liquido_reais)}\n          </td>\n          <td class=\"py-3 px-4 text-right\">\n            <button onclick=\"abrirModalRastreabilidade('${d.numero_documento}')\" class=\"px-2.5 py-1 ${d.alerta_corrupcao ? 'bg-[#dc2626] hover:bg-[#b91c1c] text-white border-red-600' : 'bg-emerald-50 hover:bg-emerald-100 text-emerald-800 border-emerald-300'} border rounded text-[11px] font-bold transition-colors\">\n              ${d.alerta_corrupcao ? 'Auditar' : 'Rastrear'}\n            </button>\n          </td>\n        </tr>\n      `;\n    }).join('');\n  } catch (err) {\n    tbody.innerHTML = '<tr><td colspan=\"7\" class=\"py-4 text-center text-xs text-red-600\">Erro ao carregar despesas.</td></tr>';\n  }\n}\n\n// 9. Modal de Rastreabilidade & Proveniência com Destaque de Corrupção\nasync function abrirModalRastreabilidade(docId) {\n  const modal = document.getElementById('modalRastreabilidade');\n  const conteudo = document.getElementById('conteudoModal');\n  modal.classList.remove('hidden');\n\n  conteudo.innerHTML = `\n    <div class=\"py-8 text-center\">\n      <svg class=\"animate-spin inline-block w-6 h-6 text-[#002776] mb-2\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\">\n        <circle class=\"opacity-25\" cx=\"12\" cy=\"12\" r=\"10\" stroke=\"currentColor\" stroke-width=\"4\"></circle>\n        <path class=\"opacity-75\" fill=\"currentColor\" d=\"M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z\"></path>\n      </svg>\n      <p class=\"text-slate-600 text-xs\">Consultando linagem contábil e hash SHA-256 do documento ${docId}...</p>\n    </div>\n  `;\n\n  try {\n    const res = await fetch(`/api/v1/rastreabilidade/${docId}`);\n    if (!res.ok) throw new Error('Documento não encontrado');\n    const rastro = await res.json();\n\n    const temAlertaCorrupcao = rastro.auditoria_corrupcao && rastro.auditoria_corrupcao.alerta_ativo;\n\n    conteudo.innerHTML = `\n      <div class=\"space-y-4\">\n        \n        <!-- BANNER VERMELHO SE HOUVER INDÍCIO DE CORRUPÇÃO -->\n        ${temAlertaCorrupcao ? `\n          <div class=\"bg-red-50 border border-red-300 p-4 rounded-xl space-y-2 shadow-xs\">\n            <div class=\"flex items-center justify-between text-red-800 font-extrabold text-xs uppercase tracking-wide\">\n              <span class=\"flex items-center gap-1.5\">\n                ${svgAlertTriangle}\n                <span>INDÍCIO DE CORRUPÇÃO / IRREGULARIDADE GRAVE DETECTADO</span>\n              </span>\n              <span class=\"text-[10px] font-mono bg-[#dc2626] text-white px-2 py-0.5 rounded font-bold\">ALERTA AUDITORIA</span>\n            </div>\n            <p class=\"text-red-900 text-xs font-semibold leading-relaxed\">\n              ${rastro.auditoria_corrupcao.motivo}\n            </p>\n            <div class=\"text-[10px] text-red-700 font-mono font-medium\">\n              Classificação do Risco: <strong>${rastro.auditoria_corrupcao.tipo_risco}</strong> • Encaminhar denúncia aos órgãos de controle (TCU / CGU / MPF)\n            </div>\n          </div>\n        ` : ''}\n\n        <!-- Resumo do Documento -->\n        <div class=\"bg-slate-50 p-4 rounded-xl border border-slate-200 space-y-2\">\n          <div class=\"flex items-center justify-between\">\n            <span class=\"text-xs uppercase tracking-wider text-slate-500 font-semibold\">Documento Oficial</span>\n            <span class=\"font-mono tabular-nums text-[#002776] font-bold\">${rastro.documento.tipo} nº ${rastro.documento.numero}</span>\n          </div>\n          <div class=\"text-xl font-black ${temAlertaCorrupcao ? 'text-red-700' : 'text-emerald-800'} font-mono tabular-nums\">\n            ${formatarMoeda(rastro.valor_liquido)}\n          </div>\n          <div class=\"text-xs text-slate-700\">\n            <strong>Fase Contábil:</strong> ${rastro.fase}\n            ${rastro.is_transferencia ? ' • <span class=\"text-sky-700 font-semibold\">Repasse Intergovernamental (Fundo a Fundo)</span>' : ''}\n          </div>\n        </div>\n\n        <!-- Órgão e Favorecido -->\n        <div class=\"grid grid-cols-2 gap-3\">\n          <div class=\"bg-slate-50 p-3 rounded-lg border border-slate-200\">\n            <div class=\"text-[10px] uppercase text-slate-500 font-bold\">Órgão Emissor</div>\n            <div class=\"font-semibold text-slate-900 mt-1\">${rastro.orgao}</div>\n            <div class=\"text-[11px] text-slate-500 font-mono mt-0.5\">${rastro.ug}</div>\n          </div>\n          <div class=\"bg-slate-50 p-3 rounded-lg border border-slate-200\">\n            <div class=\"text-[10px] uppercase text-slate-500 font-bold\">Favorecido / Credor</div>\n            <div class=\"font-semibold text-slate-900 mt-1\">${rastro.favorecido.nome}</div>\n            <div class=\"text-[11px] text-amber-800 font-mono tabular-nums mt-0.5\">${rastro.favorecido.documento}</div>\n          </div>\n        </div>\n\n        <!-- Proveniência Forense & Integridade Criptográfica -->\n        <div class=\"bg-slate-50 border border-slate-200 p-3.5 rounded-xl space-y-2\">\n          <div class=\"flex items-center justify-between text-[#002776] text-xs font-semibold\">\n            <span>Rastreabilidade Oficial (Lei nº 12.527 / LAI)</span>\n            <span class=\"text-[10px] font-mono bg-emerald-50 text-emerald-800 border border-emerald-200 px-2 py-0.5 rounded font-bold\">STATUS: AUTÊNTICO</span>\n          </div>\n          <div class=\"space-y-1 text-[11px] text-slate-700\">\n            <div><strong>Fonte Oficial:</strong> ${rastro.auditoria_proveniencia.fonte_oficial}</div>\n            <div class=\"break-all font-mono text-[10px] text-slate-600\">\n              <strong>Hash SHA-256 do Registro:</strong><br>\n              ${rastro.auditoria_proveniencia.hash_sha256}\n            </div>\n            <div class=\"text-slate-500 text-[10px] tabular-nums\">\n              <strong>Data de Extração:</strong> ${rastro.auditoria_proveniencia.data_ingestao}\n            </div>\n          </div>\n        </div>\n\n        <!-- Ação Oficial -->\n        <div class=\"pt-1\">\n          <a href=\"${rastro.auditoria_proveniencia.url_oficial}\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"w-full flex items-center justify-center gap-2 py-2.5 px-4 bg-[#00853b] hover:bg-[#006b2f] text-white font-bold rounded-xl transition-all shadow-xs text-xs\">\n            <span>Ver Comprovante no Portal da Transparência</span>\n            ${svgExternalLink}\n          </a>\n        </div>\n      </div>\n    `;\n  } catch (err) {\n    conteudo.innerHTML = `<div class=\"py-4 text-center text-red-600\">${err.message}</div>`;\n  }\n}\n\nfunction fecharModal() {\n  document.getElementById('modalRastreabilidade').classList.add('hidden');\n}\n\n// Expõe funções globais para manipulação de eventos inline\nwindow.abrirModalRastreabilidade = abrirModalRastreabilidade;\nwindow.navegarParaAba = navegarParaAba;\n";
